# gen-parks2.ps1 — full national park guides (replace stubs). Pure ASCII.
. "$PSScriptRoot/gen-common.ps1"
function New-Park($slug,$name,$country,$imgk,$lead,$wild,$time,$access,$stays,$days,$safaris,$combo,$fu){
  if($safaris.Count -gt 0 -and $safaris[0] -is [string]){ $safaris = ,$safaris }
  $im=$IMG[$imgk]
  $cards=""; foreach($s in $safaris){ $cards+=Card-Pkg $s[0] $s[1] $s[2] $s[3] $s[4] $imgk }
  $faqs=$fu+(Faq-Park $name $country $time $days $combo)
  $body=Crumb @('<a href="/">Home</a>','<a href="/national-parks/">National Parks</a>',$name)
  $body+="<div class=`"hero`"><img class=`"bg`" src=`"$($im[0])`" alt=`"$($im[1])`"><div class=`"hero-in`"><p class=`"eyebrow`">$country | Park guide</p><h1>$name</h1><p class=`"sub`">$lead</p><div class=`"hero-meta`"><span class=`"pill`">$days</span><span class=`"pill`">$country</span></div><div class=`"hero-ctas`"><a class=`"btn btn-g`" href=`"/request-proposal/`">Plan a safari here</a><a class=`"btn btn-wa`" data-wa data-wa-dest=`"$name`" href=`"#`">WhatsApp</a></div></div></div>"
  $body+="<section class=`"block`"><div class=`"wrap`"><h2>Wildlife</h2><p class=`"lead`">$wild</p>"
  $body+="<h2>Best time to visit</h2><p>$time</p><h2>Getting there</h2><p>$access</p><h2>Where to stay</h2><p>$stays</p>"
  $body+="<h2>Safaris visiting $name</h2><div class=`"grid g3`">$cards</div>"
  $body+=(Faq-List $faqs)+(CTA-Band "Put $name in the right place" "Season, zone and camp selection by a specialist." $name)+"</div></section></main>"
  $canon="https://www.adventuresafariafrica.com/national-parks/$slug/"
  $html=Shell "$name Guide: Wildlife, Seasons and Safaris" "$lead" $canon $body ('<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"'+$name+' Guide"}</script>'+(Faq-Schema $faqs))
  $html | Out-File -FilePath "national-parks/$slug.html" -Encoding utf8
  "park: $slug"
}
New-Park "tarangire" "Tarangire National Park" "Tanzania" "TZ" "River, baobabs and up to 3,000 elephants - the north's great dry-season gathering." "Tarangire's dry-season elephant concentrations are the largest in northern Tanzania, joined by lions, leopards, fringe-eared oryx, gerenuk and 500-plus bird species along the river." "Best June to October when herds crowd the river; green season brings birds, babies and value." "Two hours by road from Arusha on the northern circuit - pairs with Ngorongoro and Manyara." "River-view lodges and tented camps inside and around the park; location near the river matters most in dry season." "1 to 2 days." @(@("/tanzania-safari/5-day-tanzania-safari/","5-Day Tanzania Safari","5 days | Classic","From $2,150","Tarangire plus crater and Serengeti."),@("/tanzania-safari/7-day-tanzania-safari/","7-Day Tanzania Safari","7 days | Migration","From $3,450","Full northern circuit.")) "Combine with Ngorongoro Crater and Lake Manyara on any northern itinerary." @(@{"q"="Why is Tarangire best in dry season?";"a"="Water shrinks to the river, pulling elephants, buffalo and predators into one corridor - game viewing per hour rivals anywhere in the north."},@{"q"="Can Tarangire fill a full day?";"a"="Easily: river loops morning and afternoon, picnic at picnic sites, plus night-drive options from outside-park lodges."},@{"q"="Is Tarangire good for birding?";"a"="Superb - 500-plus species including endemic yellow-collared lovebirds, Kori bustards and seven owl species."})
New-Park "lake-manyara" "Lake Manyara National Park" "Tanzania" "TZ" "Forest, flamingos and tree-climbing lions - the perfect half-day between giants." "Groundwater forest elephants, the famous tree-climbing lions, hippo pools, and a soda lake streaked pink with flamingos - huge variety in a compact 330 sq km." "Wildlife year-round; flamingo numbers peak after rains; dry months easiest for lions." "90 minutes from Arusha, on the road between Tarangire and Ngorongoro - almost every northern circuit passes the gate." "Forest lodges and highland farms nearby; many visitors sleep at Karatu and visit en route." "Half to 1 day." @(@("/tanzania-safari/5-day-tanzania-safari/","5-Day Tanzania Safari","5 days","From $2,150","Includes Manyara options."),@("/tanzania-safari/9-day-tanzania-safari/","9-Day Grand North","9 days","From $3,750","Every northern park.")) "Slot between Tarangire and the crater - never a standalone destination." @(@{"q"="Will we really see tree-climbing lions?";"a"="Often but never guaranteed - they favor sausage-tree branches near the lake. Morning visits during dry months give the best odds."},@{"q"="Is the canopy walkway worth it?";"a"="Yes for families and photographers: 400 meters of suspended walkway through the forest canopy with lake views."},@{"q"="How long do we need?";"a"="Half a day suffices; a full day only for serious birders working the lake and forest lists."})
New-Park "ruaha" "Ruaha National Park" "Tanzania" "TZ" "Tanzania's biggest park and its wildest - prides, dogs and 570 birds with no crowds." "Huge lion prides, African wild-dog packs, greater and lesser kudu, sable, roan and 570 bird species along the Great Ruaha River - a predator density that surprises first-timers." "June to October dry season concentrates game at water; green season is lush, bird-rich and superb value." "Fly-in from Arusha or Dar (90 minutes) - road transfers are full-day expeditions." "Fly-in tented camps along the river systems; 3-plus nights minimum to justify the flight." "3 or more days." @(@("/southern-tanzania-safari/5-day-ruaha-safari/","5-Day Ruaha Safari","5 days | Fly-in","From $2,400","Prides, dogs, no crowds."),@("/southern-tanzania-safari/10-day-southern-tanzania/","10-Day Southern Grand","10 days","From $4,400","Ruaha plus Nyerere.")) "Pair with Nyerere for the complete wild south, or as a fly-in finale to a northern trip." @(@{"q"="Why is Ruaha still quiet?";"a"="Distance and fly-in cost filter crowds - the reward is sightings with one vehicle instead of twenty."},@{"q"="What are wild-dog odds?";"a"="Among Tanzania's best: several resident packs den in the park. Dry season gives the highest encounter rates."},@{"q"="Ruaha or Serengeti for lions?";"a"="Serengeti for sheer numbers and Migration drama; Ruaha for huge prides in total solitude."})
New-Park "nyerere" "Nyerere National Park (Selous)" "Tanzania" "TZ" "Africa's largest reserve: Rufiji boats, walking safaris and wild-dog country." "Boat safaris past wallowing elephants and hippo pods, wild dogs, big lion prides, and walking safaris with armed guides - plus 440 bird species in riverine forest." "June to October for boats, walks and dry-country game; green season brings birds and lower rates." "Fly-in from Dar es Salaam or Zanzibar (45-60 minutes); road from Dar is 5-6 hours." "River lodges and tented camps; boat-and-walk concessions cluster along the Rufiji." "2 to 3 days." @(@("/southern-tanzania-safari/4-day-nyerere-safari/","4-Day Nyerere Safari","4 days","From $1,750","River, road and foot."),@("/tanzania-safari-from-zanzibar/3-day-safari-from-zanzibar/","3-Day from Zanzibar","3 days","From $1,550","Shortest full safari from the island.")) "Combine with Ruaha for the wild south, or Mikumi for an easy Dar es Salaam loop." @(@{"q"="What makes Nyerere different from Serengeti?";"a"="Water and feet: Rufiji boat safaris and walking safaris are forbidden in most national parks but standard here."},@{"q"="Is Nyerere a Big Five park?";"a"="Yes - lion, leopard, elephant, buffalo and (rarely seen) rhino, plus wild dogs which many travelers rate higher."},@{"q"="Day trip from Zanzibar possible?";"a"="Yes to Nyerere and Mikumi only: early flight out, game activities, evening flight back. Serengeti needs at least two days."})
New-Park "amboseli" "Amboseli National Park" "Kenya" "KE" "Great tuskers under Kilimanjaro - Africa's most photographed elephants." "Over 400 elephants including some of Africa's last great tuskers, plus lions, cheetahs and vast flamingo-flecked lake beds - all under Kilimanjaro, clearest at dawn." "January to March for clearest mountain views; June to October for dry-season game density." "Four hours by road from Nairobi; fly-in strips available." "Lodges facing the mountain for dawn views; swamp-side camps for elephant proximity." "2 days." @(@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya Safari","7 days","From $3,100","Amboseli plus lakes and Mara."),@("/kenya-safari/3-day-amboseli-safari/","3-Day Amboseli Safari","3 days","From $1,200","Tuskers and Kili views.")) "Pair with the Mara for cats-plus-tuskers, or Tsavo for south-Kenya depth." @(@{"q"="Will we actually see Kilimanjaro?";"a"="Most dawns in January to March: the mountain reveals at sunrise then clouds over by 10am. Build two mornings for insurance."},@{"q"="What is a great tusker?";"a"="An elephant whose tusks reach the ground - Amboseli shelters Africa's last significant population, monitored by researchers."},@{"q"="Is two days enough?";"a"="Yes: afternoon arrival drive, full second day, dawn third morning. Longer only for photographers staking swamp crossings."})
New-Park "samburu" "Samburu & Buffalo Springs" "Kenya" "KE" "Rugged northern beauty and the Special Five found nowhere else in Kenya." "Grevy's zebra, reticulated giraffe, gerenuk, Beisa oryx and Somali ostrich along the Ewaso Nyiro river, with leopards in the riverine forest and strong elephant herds." "June to October dry season; green season brings dramatic skies and fewer vehicles." "Five to six hours by road from Nairobi, or fly-in to Samburu strips." "River-side lodges and tented camps; community conservancies add night drives and walks." "2 to 3 days." @(@("/kenya-safari-from-nairobi/8-day-kenya-from-nairobi/","8-Day + Samburu","8 days","From $3,550","North plus south Kenya."),@("/kenya-safari-from-nairobi/10-day-kenya-from-nairobi/","10-Day Grand","10 days","From $4,050","Kenya complete.")) "Contrast Samburu's arid specials with the Mara's plenty on 8-plus-day loops." @(@{"q"="What is the Special Five?";"a"="Grevy's zebra, reticulated giraffe, gerenuk, Beisa oryx and Somali ostrich - northern species absent from southern Kenya parks."},@{"q"="Is Samburu safe and accessible?";"a"="Yes on standard tourist circuits with normal precautions; roads are good and lodges well established."},@{"q"="Samburu or Amboseli for a second park?";"a"="Samburu for unique species and rugged scenery; Amboseli for elephants plus Kilimanjaro. Mara pairs with either."})
New-Park "lake-naivasha" "Naivasha, Nakuru & the Rift Lakes" "Kenya" "KE" "Boats, walks and rhinos - the Rift Valley's activity break between drives." "Boat safaris past hippo pods, walking with wildlife on Crescent Island, black and white rhinos at Nakuru, and flamingo-fringed shores - the perfect mid-loop breather." "Year-round; flamingo numbers shift with lake levels - ask for current counts." "Two hours by road from Nairobi, midway to the Mara." "Lakeside lodges, Naivasha guesthouses and Nakuru-view hotels." "1 to 2 days." @(@("/kenya-safari/7-day-kenya-safari/","7-Day Kenya Safari","7 days","From $3,100","Lakes plus Mara and Amboseli."),@("/kenya-safari-from-nairobi/5-day-kenya-from-nairobi/","5-Day Mara and Lakes","5 days","From $2,000","Compact loop.")) "Slot between Nairobi and the Mara on every classic loop." @(@{"q"="Can we walk with wildlife?";"a"="Yes on Crescent Island: a guided walk among giraffe, zebra and gazelles with no predators present."},@{"q"="Nakuru or Naivasha for rhinos?";"a"="Nakuru's sanctuary holds both black and white rhino reliably; Naivasha is about boats, birds and walks."},@{"q"="Are the flamingos guaranteed?";"a"="No - lake levels shift birds between Nakuru, Bogoria and Natron. We check current concentrations when routing."})
New-Park "kruger" "Kruger & Sabi Sand" "South Africa" "SA" "Big Five plus the continent's most reliable leopards - self-drive or suite." "Sabi Sand's off-road traversing delivers unmatched leopard viewing; the public park offers lion, elephant, buffalo, rhino and 500-plus birds on affordable self-drive circuits." "May to September dry winter for game viewing (cold dawns); November to March for birds and babies." "Fly to Skukuza/Nelspruit plus transfer, or 5-hour drive from Johannesburg; Sabi Sand has private airstrips." "Sabi Sand suites for luxury; Kruger rest camps for self-drives; Thornybush/Timbavati mid-tier concessions." "3 to 5 days." @(@("/south-africa-safari/5-day-kruger-safari/","5-Day Kruger Safari","5 days","From $2,800","Sabi Sand concession."),@("/south-africa-safari/9-day-south-africa/","9-Day Cape and Kruger","9 days","From $4,900","Bush plus city.")) "Pair with Cape Town and the winelands, or the Garden Route for the grand loop." @(@{"q"="Self-drive or private lodge?";"a"="Self-drive Kruger is cheap and fun; private concessions cost more but deliver off-road leopard sightings you cannot get in the public park. We quote both."},@{"q"="Sabi Sand or Timbavati?";"a"="Sabi Sand for peak leopard density; Timbavati for value with traversing rights. Both allow night drives and walks."},@{"q"="Is Kruger malaria-free?";"a"="No - low to moderate risk, prophylaxis advised. For strictly malaria-free Big Five, choose Madikwe or Eastern Cape reserves."})
New-Park "etosha" "Etosha National Park" "Namibia" "NA" "Waterhole theatre: lions, black rhino and vast herds circling desert water." "Dry-season game viewing at its simplest - lions, black and white rhino, huge springbok and zebra herds at Nebrownii, Goas and floodlit Okaukuejo, plus 340 bird species." "May to October dry season; wet months scatter game but bring birds and newborns." "Four to five hours by road from Windhoek; Anderson and Von Lindequist gates." "Waterhole-view camps (Okaukuejo, Halali, Namutoni) plus Ongava private concession for luxury." "2 to 3 days." @(@("/namibia-safari/10-day-namibia-safari/","10-Day Grand Loop","10 days","From $4,200","Dunes to waterholes."),@("/namibia-safari/7-day-namibia-safari/","7-Day Highlights","7 days","From $2,900","Desert half of the loop.")) "Close every grand loop here after dunes, coast and Damaraland." @(@{"q"="Which waterholes are best?";"a"="Nebrownii and Goas by day; Okaukuejo's floodlit hole after dinner for black rhino. Guides rotate by recent activity."},@{"q"="Self-drive or guided in Etosha?";"a"="Self-drive works brilliantly - flat roads, clear maps. Guided adds radio-network sightings and night-drive options from lodges."},@{"q"="How does Etosha compare to the Serengeti?";"a"="Different genius: concentrated waterhole viewing versus vast Migration drama. Etosha is easier, cheaper and superb for rhino."})
New-Park "sossusvlei" "Sossusvlei & Namib-Naukluft" "Namibia" "NA" "300-metre red dunes, Deadvlei's white clay pan - Africa's great desert icons." "Climb Big Daddy at dawn, walk Deadvlei among 900-year-old camelthorn skeletons, descend Sesriem Canyon, and watch oryx and springbok cross red sand." "Year-round; summer heat November to March is fierce - dawn starts mandatory." "Five hours from Windhoek; stay inside the park gates for sunrise access." "Dune lodges with gate access (a huge dawn advantage) plus Sesriem campsites." "1 to 2 days." @(@("/namibia-safari/7-day-namibia-safari/","7-Day Highlights","7 days","From $2,900","Dunes, coast, rhinos."),@("/namibia-self-drive/","Namibia Self-Drive","7-14 days","From $2,200","Briefed 4x4 routes.")) "Open every Namibia loop, then Swakopmund coast." @(@{"q"="Big Daddy or Dune 45 for sunrise?";"a"="Big Daddy for the full Deadvlei payoff; Dune 45 for a shorter climb with classic ridge light. Fit parties do both across two dawns."},@{"q"="Do we need a 4x4 for the last 5km?";"a"="Yes - deep sand to Deadvlei/Sossusvlei requires 4x4 or the park shuttle. Sedans park at 2WD point."},@{"q"="Is a hot-air balloon available?";"a"="Yes over the dunes at dawn, seasonal - book ahead, weight limits apply."})
New-Park "chobe" "Chobe National Park" "Botswana" "BW" "Riverfront elephant masses - 120,000 strong - watched by boat." "Afternoon boat safaris among elephant, buffalo and hippo masses on the Chobe riverfront, plus lions, sable and 450 bird species in the dry season." "May to October dry season for riverfront herds; green season disperses game but drops rates." "Fly to Kasane; road transfers to Victoria Falls (90 minutes)." "Riverfront lodges and houseboats; Khwai concession camps for predators and night drives." "2 days." @(@("/botswana-safari/5-day-botswana-safari/","5-Day Explorer","5 days","From $3,900","Chobe plus Delta."),@("/botswana-safari/8-day-botswana-safari/","8-Day Okavango and Chobe","8 days","From $7,400","Three camps.")) "Pair with the Okavango Delta, then Victoria Falls." @(@{"q"="Boat or 4x4 in Chobe?";"a"="Both: morning 4x4 for predators, afternoon boat for herds at eye level. The boat safari is the signature - never skip it."},@{"q"="When are herds biggest?";"a"="August to October, when thousands of elephants and buffalo crowd the river daily."},@{"q"="Can we add Victoria Falls?";"a"="Easily: Kasane to the Falls is a 90-minute transfer. Two nights does the Falls justice."})
New-Park "okavango-delta" "Okavango Delta" "Botswana" "BW" "A UNESCO water wilderness: mokoro canoes, island walks and predators." "Glide past elephants by mokoro dugout, walk palm islands with armed guides, and drive predator country - lions, leopards, wild dogs - from water camps." "Flood peaks June to August (mokoro prime time); game viewing strong May to October." "Fly-in only: light aircraft from Maun or Kasane to camp strips." "Water camps (mokoro plus walks) and classic land camps; 2-3 camps show both worlds." "2 to 3 days." @(@("/botswana-safari/8-day-botswana-safari/","8-Day Okavango and Chobe","8 days","From $7,400","Delta, Moremi, Chobe."),@("/botswana-safari/5-day-botswana-safari/","5-Day Explorer","5 days","From $3,900","Delta taste plus Chobe.")) "Combine water camps with Moremi/Khwai predator country." @(@{"q"="What is a mokoro safari like?";"a"="A silent poled canoe gliding reed channels past hippos and elephants - no engine, no rush, often the trip highlight."},@{"q"="Why is the flood in dry season?";"a"="Angolan rains take months to arrive: peak water June to August, long after local rains ended. Plan mokoro trips accordingly."},@{"q"="Land or water camp?";"a"="Both if budget allows: water camps for mokoro and walks, land camps for predators and night drives."})
New-Park "bwindi" "Bwindi Impenetrable Forest" "Uganda" "UG" "Half the world's mountain gorillas across misty, mountainous forest." "Twenty-plus habituated gorilla families across Buhoma, Ruhija, Rushaga and Nkuringo trailheads, plus 350 bird species and forest elephants." "Dry June to September and December to February for firm trails; permits 800 dollars, minimum age 15." "Fly to Kihihi/Kisoro strips or 8-9 hour drive from Entebbe." "Forest lodges at each trailhead - match lodge to your allocated gorilla sector." "2 to 3 days." @(@("/uganda-safari/3-day-gorilla-trekking/","3-Day Gorilla Trek","3 days","From $2,650","Fly-in, permits first."),@("/uganda-safari/7-day-uganda-safari/","7-Day Primates and Wildlife","7 days","From $4,100","Chimps, lions, gorillas.")) "Add Kibale chimps before and Queen Elizabeth savanna between." @(@{"q"="Which Bwindi sector is best?";"a"="Rushaga and Nkuringo host the most families (permit odds); Buhoma has the best lodge depth. We match sector to your dates and fitness."},@{"q"="How hard is the trek?";"a"="Moderate to tough: 1 to 5 hours on steep, muddy slopes at 2,000-3,000m. Porters carry packs and steady you - take one."},@{"q"="Uganda or Rwanda for gorillas?";"a"="Same species. Uganda permits cost 800 versus Rwanda's 1,500, and Uganda adds chimps plus savanna. Rwanda wins on transfer time."})
New-Park "kibale" "Kibale Forest National Park" "Uganda" "UG" "The primate capital: 5,000 chimps and 98-percent tracking success." "Chimpanzee tracking with near-certain success, 12 other primates, Bigodi swamp walks and crater-lake scenery." "Year-round; dry months firmest underfoot; chimps active daily regardless." "Five to six hours by road from Entebbe, en route between Murchison and Queen Elizabeth." "Crater-lake cottages and forest lodges around Fort Portal." "1 to 2 days." @(@("/uganda-safari/7-day-uganda-safari/","7-Day Primates and Wildlife","7 days","From $4,100","Chimps plus gorillas and lions."),@("/uganda-gorilla-trekking/5-day-uganda-gorilla/","5-Day Gorillas + Chimps","5 days","From $3,550","The primate double.")) "Pair with Bwindi gorillas on every primate itinerary." @(@{"q"="Chimps or gorillas if we must choose?";"a"="Gorillas for emotion, chimps for action - fast, noisy, arboreal chaos. Do both: Kibale costs a fraction of a second gorilla permit."},@{"q"="What is chimpanzee habituation (CHEX)?";"a"="A full-day alternative following researchers - deeper, slower, limited availability. Ask if standard tracking feels too brief."},@{"q"="Is Kibale worth it without gorillas?";"a"="Absolutely for primate lovers and birders - but almost everyone pairs it with Bwindi since you are already in Uganda."})
"parks2 done"
